class VideoSharingPlatform {
    struct Video {
        string content;
        int views = 0;
        int likes = 0;
        int dislikes = 0;
    };
    priority_queue<int, vector<int>, greater<int>> reused;
    int nextId = 0;
    unordered_map<int, Video> videos;

public:
    VideoSharingPlatform() {}

    int upload(string video) {
        int vid;
        if (!reused.empty()) {
            vid = reused.top();
            reused.pop();
        } else {
            vid = nextId++;
        }
        videos[vid] = {video, 0, 0, 0};
        return vid;
    }

    void remove(int videoId) {
        if (videos.count(videoId)) {
            videos.erase(videoId);
            reused.push(videoId);
        }
    }

    string watch(int videoId, int startMinute, int endMinute) {
        if (!videos.count(videoId)) return "-1";
        auto& v = videos[videoId];
        v.views++;
        int start = min(startMinute, (int)v.content.size());
        int len = max(0, min(endMinute + 1, (int)v.content.size()) - start);
        return v.content.substr(start, len);
    }

    void like(int videoId) {
        if (videos.count(videoId)) videos[videoId].likes++;
    }

    void dislike(int videoId) {
        if (videos.count(videoId)) videos[videoId].dislikes++;
    }

    vector<int> getLikesAndDislikes(int videoId) {
        if (!videos.count(videoId)) return {-1};
        return {videos[videoId].likes, videos[videoId].dislikes};
    }

    int getViews(int videoId) {
        if (!videos.count(videoId)) return -1;
        return videos[videoId].views;
    }
};

class VideoSharingPlatform {
    static class Video {
        String content;
        int views = 0;
        int likes = 0;
        int dislikes = 0;
        Video(String c) { this.content = c; }
    }
    private PriorityQueue<Integer> reused = new PriorityQueue<>();
    private int nextId = 0;
    private Map<Integer, Video> videos = new HashMap<>();

    public VideoSharingPlatform() {}

    public int upload(String video) {
        int vid = reused.isEmpty() ? nextId++ : reused.poll();
        videos.put(vid, new Video(video));
        return vid;
    }

    public void remove(int videoId) {
        if (videos.containsKey(videoId)) {
            videos.remove(videoId);
            reused.add(videoId);
        }
    }

    public String watch(int videoId, int startMinute, int endMinute) {
        if (!videos.containsKey(videoId)) return "-1";
        Video v = videos.get(videoId);
        v.views++;
        int start = Math.min(startMinute, v.content.length());
        int end = Math.min(endMinute + 1, v.content.length());
        return v.content.substring(start, end);
    }

    public void like(int videoId) {
        if (videos.containsKey(videoId)) videos.get(videoId).likes++;
    }

    public void dislike(int videoId) {
        if (videos.containsKey(videoId)) videos.get(videoId).dislikes++;
    }

    public int[] getLikesAndDislikes(int videoId) {
        if (!videos.containsKey(videoId)) return new int[]{-1};
        Video v = videos.get(videoId);
        return new int[]{v.likes, v.dislikes};
    }

    public int getViews(int videoId) {
        if (!videos.containsKey(videoId)) return -1;
        return videos.get(videoId).views;
    }
}

var VideoSharingPlatform = function() {
    this.reused = [];
    this.nextId = 0;
    this.videos = new Map();
};

/** 
 * @param {string} video
 * @return {number}
 */
VideoSharingPlatform.prototype.upload = function(video) {
    let vid;
    if (this.reused.length > 0) {
        this.reused.sort((a, b) => a - b);
        vid = this.reused.shift();
    } else {
        vid = this.nextId++;
    }
    this.videos.set(vid, { content: video, views: 0, likes: 0, dislikes: 0 });
    return vid;
};

/** 
 * @param {number} videoId
 * @return {void}
 */
VideoSharingPlatform.prototype.remove = function(videoId) {
    if (this.videos.has(videoId)) {
        this.videos.delete(videoId);
        this.reused.push(videoId);
    }
};

/** 
 * @param {number} videoId 
 * @param {number} startMinute 
 * @param {number} endMinute
 * @return {string}
 */
VideoSharingPlatform.prototype.watch = function(videoId, startMinute, endMinute) {
    if (!this.videos.has(videoId)) return "-1";
    const v = this.videos.get(videoId);
    v.views++;
    return v.content.slice(startMinute, endMinute + 1);
};

/** 
 * @param {number} videoId
 * @return {void}
 */
VideoSharingPlatform.prototype.like = function(videoId) {
    if (this.videos.has(videoId)) this.videos.get(videoId).likes++;
};

/** 
 * @param {number} videoId
 * @return {void}
 */
VideoSharingPlatform.prototype.dislike = function(videoId) {
    if (this.videos.has(videoId)) this.videos.get(videoId).dislikes++;
};

/** 
 * @param {number} videoId
 * @return {number[]}
 */
VideoSharingPlatform.prototype.getLikesAndDislikes = function(videoId) {
    if (!this.videos.has(videoId)) return [-1];
    const v = this.videos.get(videoId);
    return [v.likes, v.dislikes];
};

/** 
 * @param {number} videoId
 * @return {number}
 */
VideoSharingPlatform.prototype.getViews = function(videoId) {
    if (!this.videos.has(videoId)) return -1;
    return this.videos.get(videoId).views;
};
